import { useAsyncDebouncer } from "@tanstack/react-pacer/async-debouncer";
import type { ComponentProps } from "react";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";

export function AsyncStatefulButton({
  children,
  successLabel,
  variant,
}: {
  children: string;
  successLabel: string;
  variant?: ComponentProps<typeof StatefulButton>["variant"];
}) {
  const request = useAsyncDebouncer(async () => {}, { wait: 1200 });

  return (
    <StatefulButton
      variant={variant}
      onClick={async () => {
        await request.maybeExecute();
      }}
      successLabel={successLabel}
    >
      {children}
    </StatefulButton>
  );
}

export default function StatefulButtonDemo() {
  return (
    <div className="flex flex-wrap items-center gap-3">
      <AsyncStatefulButton successLabel="Saved">Save</AsyncStatefulButton>
      <AsyncStatefulButton successLabel="Updated" variant="outline">
        Update
      </AsyncStatefulButton>
    </div>
  );
}

import { ButtonShortcut } from "@/registry/erbium/ui/button";
import { DirectionProvider } from "@/registry/erbium/ui/direction";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";
import { AsyncStatefulButton } from "../examples/stateful-button-demo";

const Example = () => (
  <div className="flex flex-col gap-group">
    {(["ltr", "rtl"] as const).map((direction) => {
      const isRtl = direction === "rtl";
      const label = isRtl ? "حفظ" : "Save";
      const successLabel = isRtl ? "تم الحفظ" : "Saved";

      return (
        <DirectionProvider direction={direction} key={direction}>
          <div dir={direction} className="rounded-lg border p-4">
            <p className="mb-3 text-caption font-medium uppercase">{direction}</p>
            <div className="flex flex-wrap gap-3">
              <AsyncStatefulButton successLabel={successLabel}>{label}</AsyncStatefulButton>
              <StatefulButton successLabel={successLabel} variant="outline">
                {label}
                <ButtonShortcut hotkey="Mod+S" />
              </StatefulButton>
              <StatefulButton state="loading" successLabel={successLabel}>
                {label}
                <ButtonShortcut hotkey="Mod+S" />
              </StatefulButton>
              <StatefulButton state="success" successLabel={successLabel}>
                {label}
                <ButtonShortcut hotkey="Mod+S" />
              </StatefulButton>
              <StatefulButton state="success" successLabel={successLabel} variant="outline">
                {label}
              </StatefulButton>
            </div>
          </div>
        </DirectionProvider>
      );
    })}
  </div>
);

export default Example;
